functions.showToolAuthorStudio:
function showToolAuthorStudio() {
  var out = document.getElementById("output");
  out.innerHTML = "";
  out.classList.remove("hidden");
  if (typeof createConfigHeader === "function") {
    var header = createConfigHeader("ADMIN", "🔧", "Tool Author Studio", { marginBottom: "10px" });
    out.appendChild(header);
  }
  var tabBar = document.createElement("div");
  tabBar.style.cssText = "display:flex; gap:0; margin:0 12px 10px 12px; border-bottom:2px solid #e2e8f0;";
  var content = document.createElement("div");
  content.style.cssText = "padding:0 12px 12px 12px;";
  out.appendChild(tabBar);
  out.appendChild(content);
  var tabs = [
    { id: "catalog", label: "🎨 Edit Tile (Catalog)", render: _tasCatalogEditorTab },
    { id: "tool",    label: "🧩 Edit Tool Source",   render: _tasToolEditorTab },
  ];
  var activeTab = "catalog";
  function paintTabs() {
    tabBar.innerHTML = "";
    tabs.forEach(function (t) {
      var btn = document.createElement("div");
      var on = activeTab === t.id;
      btn.style.cssText = "flex:1; text-align:center; padding:10px 6px; font-size:11px; font-weight:700; cursor:pointer; transition:all 0.2s; " +
        (on ? "background:#fff; color:#1565c0; border-bottom:3px solid #1565c0; margin-bottom:-2px;" : "background:#f8fafc; color:#64748b; border-bottom:3px solid transparent;");
      btn.textContent = t.label;
      btn.onclick = function () {
        activeTab = t.id;
        paintTabs();
        content.innerHTML = "";
        t.render(content);
      };
      tabBar.appendChild(btn);
    });
  }
  paintTabs();
  // Initial render
  tabs.find(function (t) { return t.id === activeTab; }).render(content);
  if (typeof window.createPlatinumHomeBtn === "function") out.appendChild(window.createPlatinumHomeBtn());
}

functions._tasCatalogEditorTab:
function _tasCatalogEditorTab(content) {
  content.innerHTML = '<div style="padding:14px; text-align:center; font-size:11px; color:#94a3b8;">Loading catalog…</div>';
  loadFeatureData(STORE_CATALOG).then(function (rows) {
    var tiles = (rows || []).filter(function (r) { return r && r.id && String(r.id).indexOf("__") !== 0; });
    if (tiles.length === 0) {
      content.innerHTML = '<div style="padding:24px; text-align:center; font-size:11px; color:#64748b; background:#f8fafc; border:1px dashed #cbd5e1;">No catalog tiles yet. Import catalog.json or install tools to populate.</div>';
      return;
    }
    // Sort by category then order
    tiles.sort(function (a, b) {
      var ca = (a.category || "").toLowerCase(), cb = (b.category || "").toLowerCase();
      if (ca !== cb) return ca < cb ? -1 : 1;
      return (a.order || 999) - (b.order || 999);
    });
    var listHtml = '<div style="font-size:10px; color:#64748b; margin-bottom:8px;">' + tiles.length + ' tile(s). Click a row to edit metadata. Edits set <code>userOverride:true</code> so re-imports won’t clobber.</div>';
    listHtml += tiles.map(function (t, idx) {
      var stripe = idx % 2 === 0 ? "#fff" : "#f8fafc";
      var ic = t.icon || "🧩";
      var src = t.source ? '<span style="font-size:9px; color:#0d9488;">[' + _ebEsc(t.source) + ']</span>' : '<span style="font-size:9px; color:#94a3b8;">[built-in]</span>';
      var ovr = t.userOverride ? ' <span style="font-size:9px; background:#fef3c7; color:#92400e; padding:1px 5px; border-radius:0;">EDITED</span>' : '';
      return (
        '<div data-tas-tile="' + _ebEsc(t.id) + '" style="background:' + stripe + '; border:1px solid #e2e8f0; padding:8px 10px; margin-bottom:4px; cursor:pointer; display:flex; justify-content:space-between; align-items:center; gap:8px;">' +
        '<div style="flex:1; min-width:0;">' +
        '<div style="font-size:12px; font-weight:700; color:#0f172a;">' + ic + ' ' + _ebEsc(t.title || t.id) + ovr + '</div>' +
        '<div style="font-size:9px; color:#64748b; margin-top:2px;">' + _ebEsc(t.category || "(no category)") + ' · ' + src + '</div>' +
        '</div>' +
        '<button class="tas-edit-btn" style="padding:3px 8px; font-size:10px; cursor:pointer; background:#1565c0; color:#fff; border:none;">Edit</button>' +
        '</div>'
      );
    }).join("");
    content.innerHTML = listHtml;
    content.querySelectorAll("[data-tas-tile]").forEach(function (row) {
      row.onclick = function () {
        var id = row.getAttribute("data-tas-tile");
        var tile = tiles.filter(function (t) { return t.id === id; })[0];
        if (tile) _tasOpenCatalogForm(tile, content);
      };
    });
  });
}

functions._tasOpenCatalogForm:
function _tasOpenCatalogForm(tile, content) {
  var formHtml =
    '<button id="tasBack" style="margin-bottom:8px; padding:4px 10px; font-size:10px; cursor:pointer; background:#fff; border:1px solid #cbd5e1; color:#64748b;">← Back to list</button>' +
    '<div style="background:#fff; border:1px solid #e2e8f0; padding:14px;">' +
    '<div style="font-size:13px; font-weight:800; color:#0f172a; margin-bottom:10px;">Edit tile: ' + _ebEsc(tile.id) + '</div>' +
    _tasField("tasIcon", "Icon (emoji)", tile.icon || "", "text") +
    _tasField("tasTitle", "Title", tile.title || "", "text") +
    _tasField("tasDesc", "Description", tile.desc || "", "text") +
    _tasField("tasHover", "Hover tip", tile.hoverTip || "", "text") +
    _tasField("tasCat", "Category", tile.category || "", "text") +
    _tasField("tasOrder", "Order (number)", String(tile.order != null ? tile.order : ""), "number") +
    _tasField("tasTags", "Tags (comma-separated)", (tile.tags || []).join(", "), "text") +
    '<label style="display:flex; align-items:center; gap:6px; font-size:11px; color:#475569; margin:6px 0;"><input type="checkbox" id="tasReqApi"' + (tile.requiresApiKey ? " checked" : "") + '> Requires API key</label>' +
    '<label style="display:flex; align-items:center; gap:6px; font-size:11px; color:#475569; margin:6px 0;"><input type="checkbox" id="tasCore"' + (tile.core ? " checked" : "") + '> Core (always pinned)</label>' +
    '<label style="display:flex; align-items:center; gap:6px; font-size:11px; color:#475569; margin:6px 0;"><input type="checkbox" id="tasDefault"' + (tile.default ? " checked" : "") + '> Default (auto-pin on first load)</label>' +
    _tasField("tasAction", "Action (JS string, runs on click)", tile.action || "", "text") +
    '<div style="display:flex; gap:6px; margin-top:12px;">' +
    '<button id="tasSave" style="flex:1; padding:8px; font-size:11px; font-weight:800; background:linear-gradient(135deg,#1565c0,#0d47a1); color:#fff; border:none; cursor:pointer;">💾 Save</button>' +
    '<button id="tasCancel" style="flex:1; padding:8px; font-size:11px; font-weight:700; background:#fff; color:#64748b; border:1px solid #cbd5e1; cursor:pointer;">Cancel</button>' +
    '</div>' +
    '</div>';
  content.innerHTML = formHtml;
  document.getElementById("tasBack").onclick = function () { _tasCatalogEditorTab(content); };
  document.getElementById("tasCancel").onclick = function () { _tasCatalogEditorTab(content); };
  document.getElementById("tasSave").onclick = function () {
    var updated = Object.assign({}, tile, {
      icon: document.getElementById("tasIcon").value.trim(),
      title: document.getElementById("tasTitle").value.trim(),
      desc: document.getElementById("tasDesc").value.trim(),
      hoverTip: document.getElementById("tasHover").value.trim(),
      category: document.getElementById("tasCat").value.trim(),
      order: parseInt(document.getElementById("tasOrder").value, 10) || 0,
      tags: document.getElementById("tasTags").value.split(",").map(function (s) { return s.trim(); }).filter(Boolean),
      requiresApiKey: document.getElementById("tasReqApi").checked,
      core: document.getElementById("tasCore").checked,
      default: document.getElementById("tasDefault").checked,
      action: document.getElementById("tasAction").value,
      userOverride: true,
    });
    _tasSaveCatalogRow(updated).then(function () {
      showToast("✓ Tile saved.", "success");
      _tasCatalogEditorTab(content);
    });
  };
}

functions._tasField:
function _tasField(id, label, value, type) {
  return '<label style="display:block; font-size:10px; font-weight:700; color:#64748b; margin:8px 0 3px 0; text-transform:uppercase; letter-spacing:0.3px;">' + _ebEsc(label) + '</label>' +
    '<input id="' + id + '" type="' + (type || "text") + '" value="' + _ebEsc(String(value)) + '" style="width:100%; padding:6px 8px; font-size:11px; border:1px solid #cbd5e1; box-sizing:border-box;">';
}

functions._tasToolEditorTab:
function _tasToolEditorTab(content) {
  content.innerHTML = '<div style="padding:14px; text-align:center; font-size:11px; color:#94a3b8;">Loading tools…</div>';
  loadFeatureData(STORE_JSON_TOOLS).then(function (rows) {
    var tools = (rows || []).filter(function (r) { return r && r.id && String(r.id).indexOf("__") !== 0; });
    if (tools.length === 0) {
      content.innerHTML = '<div style="padding:24px; text-align:center; font-size:11px; color:#64748b; background:#f8fafc; border:1px dashed #cbd5e1;">No tools installed. Install from Settings → Tool Manager.</div>';
      return;
    }
    var html = '<div style="font-size:10px; color:#64748b; margin-bottom:8px;">' + tools.length + ' tool(s). Click to view/edit source. Saving bumps version + re-evals immediately.</div>';
    html += tools.map(function (t, idx) {
      var stripe = idx % 2 === 0 ? "#fff" : "#f8fafc";
      var ic = (t.catalog && t.catalog.icon) || "🧩";
      var lab = (t.catalog && t.catalog.title) || t.label || t.id;
      var ver = Number(t.__version) || 0;
      var fnCount = t.functions ? Object.keys(t.functions).length : 0;
      return (
        '<div data-tas-tool="' + _ebEsc(t.id) + '" style="background:' + stripe + '; border:1px solid #e2e8f0; padding:8px 10px; margin-bottom:4px; cursor:pointer; display:flex; justify-content:space-between; align-items:center; gap:8px;">' +
        '<div style="flex:1; min-width:0;">' +
        '<div style="font-size:12px; font-weight:700; color:#0f172a;">' + ic + ' ' + _ebEsc(lab) + (ver > 0 ? ' <span style="font-size:9px; color:#1565c0;">v' + ver + '</span>' : '') + '</div>' +
        '<div style="font-size:9px; color:#64748b; margin-top:2px;">id: ' + _ebEsc(t.id) + ' · ' + fnCount + ' function(s)</div>' +
        '</div>' +
        '<button class="tas-edit-btn" style="padding:3px 8px; font-size:10px; cursor:pointer; background:#0d9488; color:#fff; border:none;">View Source</button>' +
        '</div>'
      );
    }).join("");
    content.innerHTML = html;
    content.querySelectorAll("[data-tas-tool]").forEach(function (row) {
      row.onclick = function () {
        var id = row.getAttribute("data-tas-tool");
        var tool = tools.filter(function (t) { return t.id === id; })[0];
        if (tool) _tasOpenToolForm(tool, content);
      };
    });
  });
}

functions._tasOpenToolForm:
function _tasOpenToolForm(tool, content) {
  var fnNames = tool.functions ? Object.keys(tool.functions) : [];
  var initialFn = fnNames[0] || "";
  function paint(currentFnName) {
    var src = (tool.functions && tool.functions[currentFnName]) || "";
    var html =
      '<button id="tasBack" style="margin-bottom:8px; padding:4px 10px; font-size:10px; cursor:pointer; background:#fff; border:1px solid #cbd5e1; color:#64748b;">← Back to list</button>' +
      '<div style="background:#fff; border:1px solid #e2e8f0; padding:14px;">' +
      '<div style="font-size:13px; font-weight:800; color:#0f172a; margin-bottom:8px;">' + _ebEsc(tool.id) + ' (v' + (Number(tool.__version) || 0) + ')</div>' +
      '<div style="display:flex; gap:8px; align-items:center; margin-bottom:6px;">' +
      '<label style="font-size:10px; font-weight:700; color:#64748b; text-transform:uppercase;">Function:</label>' +
      '<select id="tasFnSel" style="flex:1; padding:5px; font-size:11px; border:1px solid #cbd5e1;">' +
      fnNames.map(function (n) { return '<option value="' + _ebEsc(n) + '"' + (n === currentFnName ? " selected" : "") + '>' + _ebEsc(n) + '</option>'; }).join("") +
      '</select>' +
      '</div>' +
      '<textarea id="tasFnSrc" style="width:100%; min-height:280px; max-height:500px; padding:10px; font-family:ui-monospace,Consolas,monospace; font-size:11px; line-height:1.45; border:1px solid #cbd5e1; resize:vertical; box-sizing:border-box; white-space:pre; tab-size:2;">' + _ebEsc(src) + '</textarea>' +
      '<div id="tasValidateOut" style="font-size:10px; margin:6px 0; min-height:14px;"></div>' +
      '<div style="display:flex; gap:6px; margin-top:8px;">' +
      '<button id="tasValidate" style="flex:1; padding:8px; font-size:11px; font-weight:700; background:#fff; color:#0d9488; border:1px solid #0d9488; cursor:pointer;">🧪 Validate</button>' +
      '<button id="tasSaveFn" style="flex:1; padding:8px; font-size:11px; font-weight:800; background:linear-gradient(135deg,#1565c0,#0d47a1); color:#fff; border:none; cursor:pointer;">💾 Save & Re-eval</button>' +
      '<button id="tasCancel" style="flex:1; padding:8px; font-size:11px; font-weight:700; background:#fff; color:#64748b; border:1px solid #cbd5e1; cursor:pointer;">Cancel</button>' +
      '</div>' +
      '</div>';
    content.innerHTML = html;
    document.getElementById("tasBack").onclick = function () { _tasToolEditorTab(content); };
    document.getElementById("tasCancel").onclick = function () { _tasToolEditorTab(content); };
    document.getElementById("tasFnSel").onchange = function () { paint(this.value); };
    document.getElementById("tasValidate").onclick = function () {
      var out = document.getElementById("tasValidateOut");
      var src = document.getElementById("tasFnSrc").value;
      var err = _tasValidateSource(src);
      if (err) { out.innerHTML = '<span style="color:#dc2626;">❌ ' + _ebEsc(err) + '</span>'; }
      else { out.innerHTML = '<span style="color:#0d9488;">✓ Compiles cleanly.</span>'; }
    };
    document.getElementById("tasSaveFn").onclick = function () {
      var sel = document.getElementById("tasFnSel").value;
      var src = document.getElementById("tasFnSrc").value;
      var err = _tasValidateSource(src);
      if (err) { showToast("❌ Won't save — syntax error: " + err, "error"); return; }
      tool.functions[sel] = src;
      tool.__version = (Number(tool.__version) || 0) + 1;
      _tasSaveTool(tool).then(function () {
        showToast("✓ Saved " + sel + " (v" + tool.__version + ").", "success");
        _tasToolEditorTab(content);
      });
    };
  }
  paint(initialFn);
}

functions._tasValidateSource:
function _tasValidateSource(src) {
  if (!src || !src.trim()) return "Empty source";
  try { new Function("return (\n" + src + "\n);"); return null; }
  catch (e) { return e && e.message ? e.message : "Unknown syntax error"; }
}

functions._tasSaveCatalogRow:
function _tasSaveCatalogRow(row) {
  return loadFeatureData(STORE_CATALOG).then(function (rows) {
    rows = rows || [];
    var byId = {};
    rows.forEach(function (r) { if (r && r.id) byId[r.id] = r; });
    byId[row.id] = row;
    var newRows = Object.keys(byId).map(function (k) { return byId[k]; });
    return saveFeatureData(STORE_CATALOG, newRows);
  }).then(function () {
    if (typeof _eliInvalidateCatalogCache === "function") _eliInvalidateCatalogCache();
    if (typeof _eliEnsureCatalogLoaded === "function") {
      return _eliEnsureCatalogLoaded().then(function () {
        try { if (typeof window.refreshDashboardGrid === "function") window.refreshDashboardGrid(); } catch (_) {}
      });
    }
  });
}

functions._tasSaveTool:
function _tasSaveTool(tool) {
  return loadFeatureData(STORE_JSON_TOOLS).then(function (rows) {
    rows = rows || [];
    var byId = {};
    rows.forEach(function (r) { if (r && r.id) byId[r.id] = r; });
    byId[tool.id] = tool;
    var newRows = Object.keys(byId).map(function (k) { return byId[k]; });
    return saveFeatureData(STORE_JSON_TOOLS, newRows);
  }).then(function () {
    // Re-eval the tool's functions immediately so changes take effect without reload.
    try {
      if (tool.functions && typeof tool.functions === "object") {
        Object.keys(tool.functions).forEach(function (fnName) {
          var src = tool.functions[fnName];
          if (typeof src === "string" && src.length) {
            window[fnName] = new Function("return (\n" + src + "\n);")();
          }
        });
      }
    } catch (e) { console.warn("[TAS] re-eval after save failed:", e); }
    // Sync catalog in case the tool's catalog block changed (it's the same row).
    if (typeof _dataHubSyncToolsToCatalog === "function") return _dataHubSyncToolsToCatalog();
  });
}
